```js
function createStore() {
  const tickets = new Map();
  const messages = new Map();
  const ratings = new Map();
  let nextId = 1;
  return {
    insertTicket(row) {
      const id = nextId++;
      tickets.set(id, { id, ...row });
      messages.set(id, []);
      return id;
    },
    getTicket(id) {
      const t = tickets.get(id);
      return t ? { ...t } : null;
    },
    updateTicket(id, patch) {
      const t = tickets.get(id);
      if (!t) throw new Error(`no ticket ${id}`);
      Object.assign(t, patch);
      return { ...t };
    },
    listTickets(filter = {}) {
      return [...tickets.values()].filter((t) => Object.entries(filter).every(([k, v]) => t[k] === v)).map((t) => ({ ...t }));
    },
    addMessage(ticketId, message) {
      messages.get(ticketId).push({ ...message });
    },
    getMessages(ticketId) {
      return (messages.get(ticketId) || []).map((m) => ({ ...m }));
    },
    deleteMessages(ticketId) {
      messages.set(ticketId, []);
    },
    addRating(ticketId, rating) {
      ratings.set(ticketId, { ticket_id: ticketId, ...rating });
    },
    getRating(ticketId) {
      const r = ratings.get(ticketId);
      return r ? { ...r } : null;
    },
    listRatings(filter = {}) {
      return [...ratings.values()].filter((r) => Object.entries(filter).every(([k, v]) => r[k] === v)).map((r) => ({ ...r }));
    },
  };
}

module.exports = { createStore };
```

- [ ] **Step 4: Add `rateTicket` to `src/portal.js`**

```js
'use strict';
// What a customer can do from the portal. Every function takes the signed-in customer and reads only their
// organisation's tickets.
const { STATUS, createTicket } = require('./tickets');
const { notifyAgent } = require('./notify');

function listMyTickets(store, customer) {
  return store.listTickets({ org_id: customer.orgId });
}

function getMyTicket(store, customer, id) {
  const t = store.getTicket(id);
  if (!t || t.org_id !== customer.orgId) return null;
  return { ...t, messages: store.getMessages(id) };
}

function openTicket(store, customer, { subject, body }) {
  return createTicket(store, { orgId: customer.orgId, customerId: customer.id, subject, body });
}

// The customer answers. On a resolved ticket that puts it back to open; a closed ticket takes no more answers.
function reply(store, customer, id, body, { now = new Date() } = {}) {
  const t = getMyTicket(store, customer, id);
  if (!t) return null;
  if (t.status === STATUS.CLOSED) throw new Error('this ticket is closed; please open a new one');
  store.addMessage(id, { from: 'customer', body, at: now.toISOString() });
  if (t.status === STATUS.RESOLVED || t.status === STATUS.PENDING) store.updateTicket(id, { status: STATUS.OPEN, resolved_at: null });
  return getMyTicket(store, customer, id);
}

// A customer scores a resolved ticket once, 1-5. A low score (1-2) notifies the agent who owned it.
function rateTicket(store, customer, id, score, { now = new Date() } = {}) {
  const t = getMyTicket(store, customer, id);
  if (!t) return null;
  if (t.status !== STATUS.RESOLVED) throw new Error(`cannot rate a ${t.status} ticket`);
  if (!Number.isInteger(score) || score < 1 || score > 5) throw new Error('a rating score must be a whole number from 1 to 5');
  if (store.getRating(id)) throw new Error('this ticket already has a rating');
  store.addRating(id, { score, rated_at: now.toISOString(), agent_id: t.assignee_id });
  if (score <= 2 && t.assignee_id) notifyAgent(store, t.assignee_id, { type: 'low_rating', ticketId: id, score });
  return store.getRating(id);
}

module.exports = { listMyTickets, getMyTicket, openTicket, reply, rateTicket };
```

Note: this reads `t.assignee_id` because the rename (Task 5) hasn't happened yet — Task 5 updates this one line to `t.owner_id` along with everything else.

