```js
'use strict';
// Nightly. Writes exports/rating-summary.json: one row per agent, with how many ratings their tickets
// received in the past seven days and the average score. A rating exactly seven days old is not counted —
// same direction as close-resolved.js's own age check.
const fs = require('node:fs');
const path = require('node:path');
const { EXPORT_DIR } = require('./export-tickets');

const WINDOW_DAYS = 7;
const DAY = 24 * 60 * 60 * 1000;

function summarizeRatings(store, { dir = EXPORT_DIR, now = new Date() } = {}) {
  const byAgent = new Map();
  for (const r of store.listRatings()) {
    if (!r.agent_id) continue;
    if (now.getTime() - new Date(r.rated_at).getTime() >= WINDOW_DAYS * DAY) continue;
    const scores = byAgent.get(r.agent_id) || [];
    scores.push(r.score);
    byAgent.set(r.agent_id, scores);
  }
  const summary = [...byAgent.entries()].map(([agentId, scores]) => ({
    agent_id: agentId,
    ratings: scores.length,
    average_score: Math.round((scores.reduce((sum, s) => sum + s, 0) / scores.length) * 100) / 100,
  }));
  fs.mkdirSync(dir, { recursive: true });
  const file = path.join(dir, 'rating-summary.json');
  fs.writeFileSync(file, JSON.stringify(summary, null, 2) + '\n');
  return { file, agents: summary.length };
}

module.exports = { summarizeRatings, WINDOW_DAYS };
```

